package dev.pathland.view.core

/** White-space handling for a text node (`WHITE_SPACE`). */
enum class WhiteSpace(val wire: Int) {
    /** Collapse whitespace and wrap normally (the default when absent). */
    NORMAL(0),
    /** Collapse whitespace and do not wrap. */
    NO_WRAP(1),
    /** Preserve newlines/indentation and do not wrap (code blocks). */
    PRE(2),
    /** Preserve newlines/indentation and wrap. */
    PRE_WRAP(3),
}

