import dev.pathland.view.dsl.navigate
import dev.pathland.view.dsl.padding
import dev.pathland.view.dsl.plainButtonStyle
import dev.pathland.view.core.FontDesign
import dev.pathland.view.core.TextAlignment
import dev.pathland.view.dsl.multilineTextAlignment

/** One documented protocol/DSL property. */
data class DocProperty(
    val name: String,
    val type: String,
    val description: String,
)

/** A code example on a component page. */
data class DocExample(
    val title: String,
    val description: String = "",
    val code: String,
)

/**
 * SwiftUI-style component documentation: a summary, overview, declaration,
 * optional live preview, examples, parameters, availability, notes, and links.
 */
data class ComponentDoc(
    val name: String,
    val slug: String,
    val summary: String,
    val declaration: String,
    val overview: String = "",
    val properties: List<DocProperty> = emptyList(),
    val examples: List<DocExample> = emptyList(),
    val notes: List<String> = emptyList(),
    val platforms: List<String> = listOf("Web", "GTK", "Qt"),
    val related: List<String> = emptyList(),
    val demo: (() -> View)? = null,
) {
    val route: String get() = "/docs/components/$slug"

    fun toPage(order: Int): DocsPage = DocsPage(
        sourcePath = "components/$slug.md",
        route = route,
        title = name,
        description = summary,
        section = "Components",
        order = order,
        markdown = toMarkdown(),
    )

    fun toc(): List<MarkdownHeading> = buildList {
        if (overview.isNotBlank()) add(MarkdownHeading(2, "overview", "Overview"))
        if (demo != null) add(MarkdownHeading(2, "preview", "Preview"))
        add(MarkdownHeading(2, "declaration", "Declaration"))
        if (examples.isNotEmpty()) add(MarkdownHeading(2, "examples", "Examples"))
        if (properties.isNotEmpty()) add(MarkdownHeading(2, "parameters", "Parameters"))
        if (platforms.isNotEmpty()) add(MarkdownHeading(2, "availability", "Availability"))
        if (notes.isNotEmpty()) add(MarkdownHeading(2, "notes", "Notes"))
        if (related.isNotEmpty()) add(MarkdownHeading(2, "see-also", "See Also"))
    }

    fun toMarkdown(): String = buildString {
        appendLine("# $name")
        appendLine()
        appendLine(summary)
        if (overview.isNotBlank()) {
            appendLine()
            appendLine("## Overview")
            appendLine()
            appendLine(overview)
        }
        appendLine()
        appendLine("## Declaration")
        appendLine()
        appendLine("```kotlin")
        appendLine(declaration)
        appendLine("```")
        if (examples.isNotEmpty()) {
            appendLine()
            appendLine("## Examples")
            for (example in examples) {
                appendLine()
                appendLine("### ${example.title}")
                if (example.description.isNotBlank()) {
                    appendLine()
                    appendLine(example.description)
                }
                appendLine()
                appendLine("```kotlin")
                appendLine(example.code)
                appendLine("```")
            }
        }
        if (properties.isNotEmpty()) {
            appendLine()
            appendLine("## Parameters")
            appendLine()
            appendLine("| Name | Type | Description |")
            appendLine("|---|---|---|")
            for (property in properties) {
                appendLine("| `${property.name}` | `${property.type}` | ${property.description} |")
            }
        }
        if (platforms.isNotEmpty()) {
            appendLine()
            appendLine("## Availability")
            appendLine()
            appendLine(platforms.joinToString(" · "))
        }
        if (related.isNotEmpty()) {
            appendLine()
            appendLine("## See Also")
            for (slug in related) {
                appendLine("- [$slug](/docs/components/$slug)")
            }
        }
    }
}

/** A SwiftUI-docs-style page for one component. */
@JvmOverloads
fun ComponentDocsPage(
    doc: ComponentDoc,
    repository: DocsRepository,
    siteTitle: String = "Pathland",
    homeRoute: String = "/",
): View = DocsLayout(
    page = doc.toPage(order = 100),
    repository = repository,
    siteTitle = siteTitle,
    homeRoute = homeRoute,
    tocOverride = doc.toc(),
) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 24f) {
        Text(doc.summary)
            .fontSize(18f)
            .foregroundStyle(Color.token("color.text.secondary"))

        if (doc.overview.isNotBlank()) {
            DocSection("Overview", "overview")
            Markdown(doc.overview)
        }

        if (doc.demo != null) {
            DocSection("Preview", "preview")
            PreviewCard(doc.demo)
        }

        DocSection("Declaration", "declaration")
        CodeBlock(doc.declaration, "kotlin")

        if (doc.examples.isNotEmpty()) {
            DocSection("Examples", "examples")
            for (example in doc.examples) {
                VStack(alignment = HorizontalAlignment.LEADING, spacing = 8f) {
                    Text(example.title).font(Font.headline())
                    if (example.description.isNotBlank()) {
                        Text(example.description)
                            .foregroundStyle(Color.token("color.text.secondary"))
                    }
                    CodeBlock(example.code, "kotlin")
                }
            }
        }

        if (doc.properties.isNotEmpty()) {
            DocSection("Parameters", "parameters")
            PropertyTable(doc.properties)
        }

        if (doc.platforms.isNotEmpty()) {
            DocSection("Availability", "availability")
            HStack(spacing = 8f) {
                for (platform in doc.platforms) {
                    Text(platform)
                        .fontSize(11f)
                        .fontWeight(FontWeight.SEMIBOLD)
                        .padding(top = 3f, right = 8f, bottom = 3f, left = 8f)
                        .background(Color.token("color.surface"))
                        .border(Color.token("color.border"), 1f, 6f)
                }
            }
        }

        if (doc.notes.isNotEmpty()) {
            DocSection("Notes", "notes")
            VStack(alignment = HorizontalAlignment.LEADING, spacing = 6f) {
                for (note in doc.notes) {
                    Text("• $note")
                        .foregroundStyle(Color.token("color.text.secondary"))
                }
            }
        }

        if (doc.related.isNotEmpty()) {
            DocSection("See Also", "see-also")
            HStack(spacing = 12f) {
                for (slug in doc.related) {
                    Text("[${humanize(slug)}](/docs/components/$slug)")
                }
            }
        }
    }
}

/** A SwiftUI-docs-style index of every component. */
@JvmOverloads
fun ComponentDocsIndexPage(
    page: DocsPage,
    docs: List<ComponentDoc>,
    repository: DocsRepository,
    siteTitle: String = "Pathland",
    homeRoute: String = "/",
): View = DocsLayout(
    page = page,
    repository = repository,
    siteTitle = siteTitle,
    homeRoute = homeRoute,
    tocOverride = emptyList(),
) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 16f) {
        Text(
            "Every Pathland primitive, container, and control, documented in the " +
                "same shape: overview, declaration, live preview, examples, and parameters.",
        ).fontSize(18f).foregroundStyle(Color.token("color.text.secondary"))

        Grid(columns = 3, spacing = 16f) {
            for (doc in docs) {
                Button(action = {}) {
                    VStack(alignment = HorizontalAlignment.LEADING, spacing = 6f) {
                        Text(doc.name).font(Font.headline())
                        Text(doc.summary)
                            .fontSize(13f)
                            .foregroundStyle(Color.token("color.text.secondary"))
                    }
                    .padding(16f)
                }
                .buttonStyle(plainButtonStyle())
                .background(Color.token("color.surface"))
                .border(Color.token("color.border"), 1f, 10f)
                .navigate(doc.route)
            }
        }
    }
}

private fun DocSection(title: String, id: String) {
    Text(title).font(Font.title2()).anchor(id)
}

private fun PreviewCard(demo: () -> View) {
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 12f) {
        Text("LIVE PREVIEW")
            .fontSize(10f)
            .fontWeight(FontWeight.SEMIBOLD)
            .foregroundStyle(Color.token("color.text.secondary"))
        demo()
    }
    .padding(20f)
    .background(Color.token("color.surface"))
    .border(Color.token("color.border"), 1f, 10f)
}

