                .groupingBy { it }
                .eachCount()
                .filterValues { it > 1 }
                .keys
                .map { "${page.sourcePath}: $it" }
        }
        assertTrue(duplicates.isEmpty(), "duplicate live ids: $duplicates")
    }
}
