/**
 * Structurally validate a batch before applying any mutation. A malformed batch
 * is rejected atomically (no half-applied DOM), and unknown value types can no
 * longer fall through into the numeric property path.
 */
function validateBatch(batch: Batch, renderer: DomRenderer): void {
  let created = 0;
  for (const op of batch.opcodes) {
    switch (op.category) {
      case CAT_TREE:
        if (op.command === CMD_CREATE_NODE) {
          if (op.b > 0xffff) {
            throw new ProtocolError(`invalid component id ${op.b}`);
          }
          created++;
        }
        break;
      case CAT_PARAMETER:
        validateParameter(op, batch.strings);
        break;
      case CAT_META:
        if (op.command === CMD_SET_WINDOW_METADATA) {
          readString(batch.strings, op.b);
        }
        break;
      default:
        break;
    }
  }
  if (renderer.byId.size + created > MAX_NODES) {
    throw new ProtocolError("node limit exceeded");
  }
}

function validateParameter(op: Opcode, strings: Uint8Array): void {
  switch (op.command) {
    case CMD_SET_TEXT:
      readString(strings, op.b);
      break;
    case CMD_SET_DESIGN_TOKEN: {
      readString(strings, op.a); // token path
      if ((op.b & 0xff) === VAL_STRING) {
        readString(strings, op.c); // string-valued token override
      }
      break;
    }
    case CMD_SET_ATTRIBUTED_TEXT:
      readAttributed(strings, op.b);
      break;
    case CMD_SET_PROPERTY: {
      const valueType = (op.b >>> 16) & 0xff;
      if (!KNOWN_VALUE_TYPES.has(valueType)) {
        throw new ProtocolError(`unknown value type ${valueType}`);
      }
      if (valueType === VAL_STRING || valueType === VAL_DESIGN_TOKEN) {
        readString(strings, op.c);
      } else if (valueType === VAL_LIST) {
        readList(strings, op.c);
      }
      break;
    }
    default:
      break;
  }
}

/** Apply every opcode in a batch to the DOM (TREE structure + PARAMETER/META deltas). */
export function applyBatch(batch: Batch, renderer: DomRenderer): void {
  validateBatch(batch, renderer);
  // SSR snapshot fit slots (`data-pathland-fit-cands`) touched by a structural
  // removal in this batch. The gate is torn down AFTER the whole batch, gated on
  // the slot's FINAL state (issue #141): a removal that does NOT reduce the slot
  // to a single live candidate (e.g. a band-crossing fit swap dropping a child
  // inside a candidate) must leave the gate intact — unwrapping it eagerly would
  // expose every candidate (the "all branches rendered" bug).
  const touchedFitGates = new Set<HTMLElement>();
  for (let i = 0; i < batch.opcodes.length; i++) {
    const op = batch.opcodes[i]!;
    try {
      switch (op.category) {
        case CAT_TREE:
          applyTree(op, renderer, touchedFitGates);
          break;
        case CAT_PARAMETER:
          applyStyle(op, batch.strings, renderer);
          break;
        case CAT_META:
          applyMeta(op, batch.strings, renderer);
          break;
        default:
          break;
      }
    } catch (err) {
      // The batch is a renderer-consuming instruction stream; an empty catch
      // would hide a structural bug. Log the exact op for remote diagnosis,
      // then rethrow (the host's handleMessage surfaces it).
      const el = renderer.byId.get(op.a);
      const where = el instanceof Element
        ? `${el.tagName.toLowerCase()}#${el.getAttribute("data-pathland-id")}.${el.className}`
        : String(el);
      console.error(
        `[pathland] applyBatch failed at op ${i}/${batch.opcodes.length} ` +
        `cat=${op.category} cmd=${op.command} a=${op.a} b=${op.b} c=${op.c} target=${where}`, err);
      throw err;
    }
  }
  for (const slot of touchedFitGates) {
    reconcileFitGate(slot);
    reconcileFitGate(slot);
  }
  // Derived layout (fill propagation, ZStack sizing/positioning, cross-axis
  // align-self) — mirrors the Rust SSR renderer's whole-tree decisions.
  applyLayout(renderer);
}

function applyMeta(op: Opcode, strings: Uint8Array, r: DomRenderer): void {
  switch (op.command) {
    case CMD_RESET: {
      for (const el of Array.from(r.byId.values())) {
        if (el.parentNode) {
          el.parentNode.removeChild(el);
        }
      }
      r.byId.clear();
      break;
    }
    case CMD_SET_COLOR_SCHEME: {
      const root = document.documentElement;
      if (op.a === COLOR_SCHEME_LIGHT) {
        root.dataset.pathlandScheme = "light";
      } else if (op.a === COLOR_SCHEME_DARK) {
        root.dataset.pathlandScheme = "dark";
      } else {
        delete root.dataset.pathlandScheme;
      }
      break;
    }
    case CMD_RESET_THEME:
      (r.tokenSink ??= createTokenSink()).reset();
      break;
    case CMD_SET_WINDOW_METADATA: {
      // Renderer-global surface metadata (spec/OPCODE.md §Window metadata). The
      // browser mapping: title → document.title, description → meta description,
      // locale → <html lang>. An empty value clears the field.
      const value = readString(strings, op.b);
      switch (op.a) {
        case WINDOW_TITLE:
          document.title = value || (r.defaultTitle ?? "Pathland");
          break;
        case WINDOW_DESCRIPTION:
          setMetaDescription(value);
          break;
        case WINDOW_LOCALE:
          if (value) {
            document.documentElement.lang = value;
          } else {
            document.documentElement.removeAttribute("lang");
          }
          break;
        default:
          break;
      }
      break;
    }
    case CMD_ENVIRONMENT:
    default:
      break;
  }
}

