/// greediness).
fn fills_axis(
    nodes: &BTreeMap<u32, Node>,
    id: u32,
    axis_horizontal: bool,
    main_axis: bool,
) -> bool {
    let Some(node) = nodes.get(&id) else {
        return false;
    };
