.pathland-toggle { display: inline-flex; align-items: center; gap: var(--pl-toggle-gap); }
.pathland-toggle input[type='checkbox'] { accent-color: var(--pl-toggle-accent); width: var(--pl-toggle-checkbox-size); height: var(--pl-toggle-checkbox-size); }
